head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setFooterStyle]<br/>Cell 정보를 사용하여 특정 Footer Cell 의 Inline Style 을 설정합니다.",
    "validation" : [
        "cellInfo(필수) 파라미터로 Inline Style 을 설정할 Footer Cell 의 인덱스 또는 ID 를 설정할 수 있어야 합니다.",
        "styleName(필수) 파라미터로 설정하려는 Inline Style 의 CSS 속성명을 설정할 수 있어야 합니다.",
        "styleValue(필수) 파라미터로 CSS 속성에 적용될 속성값을 설정할 수 있어야 합니다.",
        "파라미터값에 맞게 특정 Footer Cell 에 Inline Style 이 적용되어야 합니다.",
        "Footer Cell 의 인덱스는 0 부터 시작하며 숨겨진 Footer Cell 도 포함하여 인덱스가 설정되어야 합니다.",
        "RowNum, RowStatus Column 의 Footer Cell 을 지정하려면 $rowNum, $rowStatus 로 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (footer 포함)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" rowNumVisible="true" rowStatusVisible="true" checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="footer1" value="footer1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="footer2" value="footer2" hidden="true"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="footer3" value="footer3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="footer4" value="footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    scwin.btn_deleteRow_onclick();
}



// Row 삭제 (D 상태 생성)
scwin.btn_deleteRow_onclick = function () {
    dlt_bind.deleteRow(0);
};



scwin.btn_setFooterStyle_onclick = function () {
    let cellInfo = par_cellInfo.getText();
    let styleName = par_styleName.getText();
    let styleValue = par_styleValue.getText();

    // cellInfo 가 숫자인 경우 Number 로 변환
    if (!isNaN(cellInfo) && cellInfo !== '') {
        cellInfo = Number(cellInfo);
    }

    target1.setFooterStyle(cellInfo, styleName, styleValue);
    wf_body_bottom.getObj("scwin").setReturnValue("setFooterStyle(" + cellInfo + ", " + styleName + ", " + styleValue + ")");

    // getFooterStyle 로 설정값 확인
    let rtn = target1.getFooterStyle(cellInfo, styleName);
    wf_body_bottom.getObj("scwin").setReturnValue("getFooterStyle(" + cellInfo + ", " + styleName + ") : " + rtn);
}
